  values
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The direction of centripetal force is:', '["Tangential to the circle","Away from the center","Towards the center","Upward"]'::jsonb, 'C', 1, '51c60fdb438e', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A 300 N boy sits 2 m from the pivot of a seesaw. A 200 N boy can balance it by sitting:', '["2 m away","3 m away","1.5 m away","4 m away"]'::jsonb, 'B', 1, 'd890af59d994', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A door opens more easily when pushed far from the hinge because:', '["Friction decreases","Torque increases due to larger moment arm","Force increases automatically","Weight decreases"]'::jsonb, 'B', 1, '63868efe4432', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A force is applied directly through the pivot point of a lever. The torque produced is:', '["Maximum","Minimum but non-zero","Zero","Depends on mass"]'::jsonb, 'C', 1, '1c7f263f2cee', null),
