    (v_chapter, 'mcq', 'concept', 'bank', 3, 'When a stone tied to a string is whirled in a circle and the string breaks, the stone moves:', '["Toward the center","In a circular path","Along the tangent to the circle","Backward"]'::jsonb, 'C', 1, '87dce24544ff', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A body topples when:', '["Its center of gravity falls outside its base","Its weight increases","Friction decreases","Its mass decreases"]'::jsonb, 'A', 1, '39a668fa241d', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A body will be most stable when it has:', '["High center of mass and narrow base","Low center of mass and wide base","High center of mass and wide base","Low center of mass and narrow base"]'::jsonb, 'B', 1, '52ef0dadc2d1', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A bus is more likely to overturn while turning if:', '["It has a low center of gravity","It moves slowly","It has a high center of gravity","Its wheels are wide apart"]'::jsonb, 'C', 1, 'e10ea6a26a23', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The center of gravity of a body is the point where:', '["All forces act","Entire weight appears to act","Friction acts","Torque is maximum"]'::jsonb, 'B', 1, '16db30ef53da', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why are ball bearings used in machines?', '["Increase friction","Reduce weight","Convert sliding friction into rolling friction","Increase torque"]'::jsonb, 'C', 1, '3ed6da905b0c', null),
