    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A force of 20 N is applied to a door. Which action produces the greatest torque?', '["Push at the hinge","Push halfway from the hinge","Push at the edge of the door perpendicular to it","Push at the edge parallel to the door"]'::jsonb, 'C', 1, '9e26a477b128', null),
